{
  "name": "Wi‑Fi连接配置模型",
  "name_en": "Wi-Fi Connection Configuration Model",
  "manufacturer": "",
  "description": "一个非物理的软件数据模型，用于表示和组织设备或系统的 Wi‑Fi 连接参数，如 SSID、安全方式、IP 地址、网关、DNS、网卡名称和子网掩码，常用于实验室设备或移动平台的网络配置提交与序列化。",
  "description_en": "A non-physical software data model used to represent and organize Wi-Fi connection parameters for a device or system, such as SSID, security mode, IP address, gateway, DNS, interface name, and netmask. It is typically used for network configuration submission and serialization in lab devices or mobile platforms.",
  "tag_hints": [
    "Wi-Fi configuration",
    "network settings",
    "SSID",
    "IP addressing",
    "DNS and gateway",
    "security mode",
    "configuration model"
  ],
  "actions": [
    {
      "action_name": "auto-address",
      "description": "获取或设置 Wi‑Fi 连接的地址参数。",
      "description_en": "Get or set the address parameter of the Wi-Fi connection."
    },
    {
      "action_name": "auto-device",
      "description": "获取或设置 Wi‑Fi 连接使用的设备或网络接口名称。",
      "description_en": "Get or set the device or network interface name used for the Wi-Fi connection."
    },
    {
      "action_name": "auto-dns",
      "description": "获取或设置 Wi‑Fi 连接的 DNS 服务器参数。",
      "description_en": "Get or set the DNS server parameter of the Wi-Fi connection."
    },
    {
      "action_name": "auto-gateway",
      "description": "获取或设置 Wi‑Fi 连接的网关参数。",
      "description_en": "Get or set the gateway parameter of the Wi-Fi connection."
    },
    {
      "action_name": "auto-netmask",
      "description": "获取或设置 Wi‑Fi 连接的子网掩码。",
      "description_en": "Get or set the netmask of the Wi-Fi connection."
    },
    {
      "action_name": "auto-security",
      "description": "获取或设置 Wi‑Fi 连接的安全方式。",
      "description_en": "Get or set the security mode of the Wi-Fi connection."
    },
    {
      "action_name": "auto-ssid",
      "description": "获取或设置 Wi‑Fi 连接的 SSID。",
      "description_en": "Get or set the SSID of the Wi-Fi connection."
    },
    {
      "action_name": "auto-to_dict",
      "description": "将该 Wi‑Fi 连接配置模型转换为字典。",
      "description_en": "Convert this Wi-Fi connection configuration model to a dictionary."
    },
    {
      "action_name": "auto-to_str",
      "description": "获取该 Wi‑Fi 连接配置模型的字符串表示。",
      "description_en": "Get the string representation of this Wi-Fi connection configuration model."
    }
  ]
}

